import React, { useState } from 'react';
//const { TimestampSeconds } = require('linearid')
import MissionSelector from './MissionSelector';
import { ModelConfigLocalSet, ModelConfigSyncSet } from '../Model';
export default function SessionPunchClockViewView(props) {
    const { ConfigLocal, ConfigLocalSet, ConfigSync, ConfigSyncSet, IsSaving, Syndicate } = props;
    let { session } = ConfigSync;
    if (session == undefined)
        return React.createElement("div", null, "undefined");
    const [MissionHeading, MissionHeadingSet] = useState('');
    const [SessionHeading, SessionHeadingSet] = useState('');
    const [SessionNumber, SessionNumberSet] = useState(0);
    const CanCancelMissionSwitch = ConfigLocal.account != ConfigSync.account ||
        ConfigLocal.mission_ids != ConfigSync.mission_ids ||
        ConfigLocal.repo != ConfigSync.repo;
    const OtherMissionSelected = ConfigLocal.account != ConfigSync.account &&
        ConfigLocal.mission_ids != ConfigSync.mission_ids &&
        ConfigLocal.repo != ConfigSync.repo;
    function TimesheetPunchHandle() {
        if (session == undefined)
            return;
        const Time = Date.now() / 1000;
        const TimeText = new Date(Time * 1000);
        if (session == 0) { // End Session
            fetch("localhost:3000/api/v1/session", {
                method: "POST"
            });
            console.log('Clocking on to Session #' + SessionNumber + ' at ' + TimeText);
            //@todo Integrate with GitHub to create Session Tickets.
            const ConfigNew = Object.assign(Object.assign({}, ConfigSync), { session: SessionNumber });
            ModelConfigSyncSet(ConfigNew);
            ConfigSyncSet(ConfigNew);
        }
        else if (session < 0) { // Stop Break
            const S = -session;
            console.log('Stopping break from Session #' + S + ' at ' + TimeText);
            const ConfigNew = Object.assign(Object.assign({}, ConfigSync), { session: S });
            ModelConfigSyncSet(ConfigNew);
            ConfigSyncSet(ConfigNew);
        }
        else { // -> Session > 0
            console.log('Clocking off from Session #' + session + ' at ' + TimeText);
            const ConfigNew = Object.assign(Object.assign({}, ConfigSync), { session: 0 });
            ModelConfigSyncSet(ConfigNew);
            ConfigSyncSet(ConfigNew);
        }
    }
    function TimesheetBreakStartHandle() {
        if (session == undefined)
            return;
        let time = Date.now() / 1000;
        console.log('Starting break from Session #' + session + ' at ' + new Date(time * 1000));
        const ConfigNew = Object.assign(Object.assign({}, ConfigSync), { session: -session });
        ModelConfigSyncSet(ConfigNew);
        ConfigSyncSet(ConfigNew);
    }
    function MissionHeadingUpdate(focus_headline) {
        MissionHeadingSet(focus_headline);
    }
    function SessionHeadingUpdate(focus_headline) {
        SessionHeadingSet(focus_headline);
    }
    return React.createElement("div", { className: 'flex flex-row m-4' },
        session == 0 && React.createElement(React.Fragment, null,
            React.createElement("input", { id: 'ClockOnOffButton', type: "button", value: "Begin Session", onClick: TimesheetPunchHandle }),
            React.createElement("input", { id: 'SessionNumberInput', type: 'number', value: SessionNumber, onChange: e => SessionNumberSet(e.target.valueAsNumber), disabled: IsSaving })),
        session > 0 && React.createElement(React.Fragment, null,
            React.createElement("input", { id: 'ClockBreakOnOffButton', type: "button", value: "End Session", onClick: TimesheetPunchHandle }),
            React.createElement("input", { id: 'TimesheetBreakButton', type: "button", value: "Start Break", onClick: TimesheetBreakStartHandle })),
        session < 0 &&
            React.createElement("input", { id: 'ClockBreakOnOffButton', type: "button", value: "Stop break", onClick: TimesheetPunchHandle }),
        session == 0 && React.createElement("div", null,
            React.createElement("span", null, "Session and Mission Heading:"),
            React.createElement("input", { type: 'text', placeholder: "Enter #SID and heading...", value: SessionHeading, onChange: (event) => SessionHeadingUpdate(event.target.value), disabled: IsSaving }),
            React.createElement("span", null, "Mission heading:"),
            React.createElement("input", { type: 'text', placeholder: "Enter mission heading...", value: MissionHeading, onChange: (event) => MissionHeadingUpdate(event.target.value), disabled: IsSaving })),
        React.createElement(MissionSelector, { ConfigLocal: ConfigLocal, ConfigLocalSet: ConfigLocalSet, ModelConfigSyncSet: ModelConfigSyncSet, Syndicate: Syndicate }),
        CanCancelMissionSwitch &&
            React.createElement("button", { onClick: () => {
                    const ConfigNew = Object.assign(Object.assign({}, ConfigLocal), { account: ConfigSync.account, repo: ConfigSync.repo, mission_ids: ConfigSync.mission_ids });
                    console.log('');
                    ConfigLocalSet(ConfigNew);
                    ModelConfigLocalSet(ConfigNew);
                } }, "Cancel"),
        OtherMissionSelected &&
            React.createElement("button", { onClick: () => {
                    const Timestamp = Date.now() / 1000;
                    let { account, mission_ids, repo } = ConfigLocal;
                    const ConfigNew = Object.assign(Object.assign({}, ConfigSync), { account: account, repo: repo, mission_ids: mission_ids });
                    console.log(new Date(Timestamp * 1000) + ': Starting mission ' + account + '/' + repo + mission_ids);
                    ConfigSyncSet(ConfigNew);
                    ModelConfigSyncSet(ConfigNew);
                } }, "Start mission"));
}
